// Discovery against the examples' known structure, on long simulated runs.
//
//     node --test tests/bench/*.test.mjs             all examples (the first run generates the data)
//     SDLAB_BENCH_EXAMPLES=kanban,flu node --test tests/bench/*.test.mjs
//
// For each example, a long run is generated by its simulator and cached outside the repository
// (tests/bench/datasets.py; rebuilt when the simulator's code changes). Discovery is then run the
// way the page runs it on:
//   growing amounts of data - the first 1/32, 1/16, ... of the run, up to all of it: does it find
//     the true structure, and does more data make it better (not worse)?
//   equal-sized slices later in the run: once settled, does it keep saying the same thing?
// The scores are printed as a table per example and written to the cache folder as
// bench-report.md. The quality checks are marked todo while discovery does not meet them yet:
// they report, but do not fail the run. Take the todo off an example when it passes.
import test from "node:test";
import assert from "node:assert";
import fs from "fs";
import path from "path";
import { spawnSync } from "child_process";
import { createRequire } from "module";
import { truthOf, grade, agreement, prediction, sameBehaviour } from "./grade.mjs";

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "../..");
const { discover, discoverAll } = require(path.join(ROOT, "sdlab/static/discover.js"));
// the search the page runs (the matrix method, sdlab/discovery, has its own bench: evaluate.py)
const ENGINE = "discover";
const EXAMPLES = (process.env.SDLAB_BENCH_EXAMPLES || "sd-pipeline,sd-saas,sd-hospital,sd-kanban,sd-supply,hospital,shop,bikeshare,library,beergame,kanban,flu,saas,reservoirs").split(",").filter(Boolean);
const FRACTIONS = [1 / 32, 1 / 16, 1 / 8, 1 / 4, 1 / 2, 1];
const SLICES = 6;

// what the quality checks expect; an example meets them when discovery is good enough on it
const GOOD = { recall: 0.5, precision: 0.5, keepsWhatItLearned: 0.1, agreement: 0.6, outsideShare: 0.6 };
// examples whose quality checks pass today (the rest are todo)
const MEETS = new Set((process.env.SDLAB_BENCH_MEETS || "").split(",").filter(Boolean));

function dataset(example) {
  const p = spawnSync("uv", ["run", "--directory", ROOT, "python", "tests/bench/datasets.py", example, "--long"], { encoding: "utf8", maxBuffer: 1 << 26 });
  if (p.status !== 0) throw new Error(`${example}: ${p.stderr.trim().split("\n").pop()}`);
  return JSON.parse(fs.readFileSync(p.stdout.trim().split("\n").pop()));
}

function slice(data, from, to) {
  return {
    t: data.t.slice(from, to),
    levels: Object.fromEntries(Object.entries(data.levels).map(([k, v]) => [k, v.slice(from, to)])),
    rates: Object.fromEntries(Object.entries(data.counters || {}).map(([k, v]) => [k, v.slice(from, to)])),
    eras: (data.eras || []).filter((e) => e.start <= data.t[to - 1]),
  };
}

// as the page does it: the whole model, 5-step windows, the run's eras, the model's measured flows
// subtracted first; split up above 12 stocks
function discoverLikeThePage(model, run) {
  const eras = run.eras.map((e) => ({ start: e.start }));
  const measured = model.flows.filter((f) => run.rates[f.id]);
  const moved = measured.length ? run.t.map((_, i) => Object.fromEntries(measured.map((f) => {
    const a = run.rates[f.id][i] || 0;
    return [f.id, { took: f.from ? { [f.from]: a } : {}, made: f.to ? { [f.to]: a } : {} }];
  }))) : undefined;
  const opts = { window: 5, eras: eras.length > 1 ? eras : undefined, moved };
  const t0 = Date.now();
  const r = model.stocks.length > 12 ? discoverAll(model.stocks, run, opts) : discover(model.stocks, run, opts);
  r.ms = Date.now() - t0;
  return r;
}

// How much the data moved: for each stock, the spread of its step-to-step changes beyond what a
// steady stock's noise would give, relative to its level; the median over stocks. A settled system
// (negative feedback holding every stock near its balance) scores near zero, and then no method
// can tell its flows apart: there is nothing to learn from.
function movement(run) {
  const v = Object.values(run.levels).map((a) => {
    if (a.length < 3) return 0;
    const mean = a.reduce((x, y) => x + y, 0) / a.length;
    let sd = 0; a.forEach((x) => { sd += (x - mean) ** 2; }); sd = Math.sqrt(sd / a.length);
    let jit = 0; for (let i = 1; i < a.length; i++) jit += (a[i] - a[i - 1]) ** 2; jit = Math.sqrt(jit / (a.length - 1) / 2);
    return Math.max(0, sd - jit) / (Math.abs(mean) + 1);   // slow swings beyond step-to-step noise
  }).sort((x, y) => x - y);
  return v.length ? v[Math.floor(v.length / 2)] : 0;
}

const pct = (x) => (x === null ? "-" : `${Math.round(100 * x)}%`);
const report = [];

for (const example of EXAMPLES) {
  test(example, async (t) => {
    const model = JSON.parse(fs.readFileSync(path.join(ROOT, "sdlab/examples", `${example}.json`)));
    const truthFile = path.join(ROOT, "sdlab/examples", example, "truth.model.json");
    const truthModel = fs.existsSync(truthFile) ? JSON.parse(fs.readFileSync(truthFile)) : null;
    const truth = truthOf(example);
    const data = dataset(example);
    const n = data.t.length;

    // growing: the first part of the run
    const growing = FRACTIONS.map((f) => Math.max(60, Math.round(n * f))).filter((len, i, a) => len <= n && a.indexOf(len) === i).map((len) => {
      const run = slice(data, 0, len), r = discoverLikeThePage(model, run);
      // behaviour: predictions 20 steps ahead over the whole run, next to the true model's
      const pred = truthModel ? prediction(r, truthModel, data) : null;
      const same = truthModel ? sameBehaviour(r, truthModel, data) : null;
      return { len, moved: movement(run), ...grade(r, truth), ms: r.ms, pred, same };
    });
    // settled: equal slices of the second half
    const size = Math.max(60, Math.floor(n / 2 / SLICES));
    const settled = Array.from({ length: SLICES }, (_, i) => {
      const from = Math.floor(n / 2) + i * size;
      const run = slice(data, from, Math.min(n, from + size));
      return { from, moved: movement(run), ...grade(discoverLikeThePage(model, run), truth) };
    });
    const agree = settled.slice(1).map((s, i) => agreement(settled[i].pairs, s.pairs));
    const meanAgree = agree.reduce((a, b) => a + b, 0) / Math.max(1, agree.length);

    const lines = [
      `## ${example}: ${n} steps, ${truth.rel.size} true relationships, ${model.stocks.length} stocks`,
      "",
      `**Parts of the true model recovered in the right form** is the headline: each true relationship named with the right kind, and each true flow to or from outside (${truth.rel.size + truth.outside.size} parts). The other columns count stock-to-stock relationships by pair.`,
      "",
      `Engine: ${ENGINE}. **Behaviour** (ground-truth examples): run the found and the true model 20 steps from many moments, both fed the truth's outside inflows; how far apart they end, as a share of how far the truth moved (0 = the same behaviour, 1 = as far apart as assuming nothing changes). **Prediction**: the found model's 20-step error against what happened, divided by the true model's (with its own estimated inflows; 1 = as good as the truth).`,
      "",
      "| steps | movement | parts right | behaviour apart | prediction vs truth | found | true pair | kind right | reversed | wrong | recall | precision | to/from outside | outside share | time |",
      "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|",
      ...growing.map((g) => `| first ${g.len} | ${g.moved.toFixed(3)} | **${g.right} of ${g.parts}** | ${g.same ? `**${g.same.apart.toFixed(3)}**` : "-"} | ${g.pred ? `${g.pred.ratio.toFixed(2)} (still ${(g.pred.still / g.pred.truth).toFixed(2)})` : "-"} | ${g.found} | ${g.hits} | ${g.kindRight} | ${g.reversed} | ${g.wrong} | ${pct(g.recall)} | ${pct(g.precision)} | ${g.outside} (${g.outsideRight} right) | ${pct(g.outsideShare)} | ${g.ms ?? ""} |`),
      ...settled.map((g) => `| ${g.from + 1} to ${g.from + size} | ${g.moved.toFixed(3)} | **${g.right} of ${g.parts}** | - | - | ${g.found} | ${g.hits} | ${g.kindRight} | ${g.reversed} | ${g.wrong} | ${pct(g.recall)} | ${pct(g.precision)} | ${g.outside} (${g.outsideRight} right) | ${pct(g.outsideShare)} | |`),
      "",
      `Agreement between consecutive slices: ${agree.map(pct).join(", ")} (mean ${pct(meanAgree)})`,
      "",
    ];
    report.push(lines.join("\n"));
    console.log(lines.join("\n"));

    const last = growing[growing.length - 1], best = Math.max(...growing.map((g) => g.recall || 0));
    const todo = MEETS.has(example) ? false : "discovery does not meet this on this example yet";
    await t.test("it runs on the whole long run", () => {
      assert.ok(n > 0 && growing.length >= 3, "a long dataset with several lengths to compare");
    });
    await t.test(`with all the data it recovers most of the true model in the right form (>= ${GOOD.recall})`, { todo }, () => {
      assert.ok((last.rightShare || 0) >= GOOD.recall, `${last.right} of ${last.parts} parts`);
    });
    await t.test(`with all the data it names most true relationships (recall >= ${GOOD.recall}, precision >= ${GOOD.precision})`, { todo }, () => {
      assert.ok((last.recall || 0) >= GOOD.recall, `recall ${pct(last.recall)}`);
      assert.ok((last.precision || 0) >= GOOD.precision, `precision ${pct(last.precision)}`);
    });
    await t.test("more data does not make it worse", { todo }, () => {
      assert.ok((last.recall || 0) >= best - GOOD.keepsWhatItLearned, `recall fell from ${pct(best)} to ${pct(last.recall)}`);
      assert.ok(last.outsideShare <= GOOD.outsideShare, `${pct(last.outsideShare)} of its flows only connect to outside`);
    });
    await t.test(`once settled it keeps saying the same thing (agreement >= ${GOOD.agreement})`, { todo }, () => {
      assert.ok(meanAgree >= GOOD.agreement, `consecutive slices agree on ${pct(meanAgree)} of their relationships`);
    });
  });
}

test.after(() => {
  const dir = process.env.SDLAB_BENCH_CACHE || path.join(process.env.HOME, ".cache", "sdlab", "bench");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, "bench-report.md"), `# Discovery on long runs (${new Date().toISOString()})\n\n${report.join("\n")}`);
});
